import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

private fun isLucky(value: Int): Boolean {
    if (value <= 0) return false
    var x = value
    while (x > 0) {
        val digit = x % 10
        if (digit != 4 && digit != 7) return false
        x /= 10
    }
    return true
}

fun main() {
    val scanner = FastScanner()
    val n = scanner.nextLong().toInt()
    val k = scanner.nextLong()

    val factorial = LongArray(14)
    factorial[0] = 1L
    for (i in 1..13) factorial[i] = factorial[i - 1] * i

    val suffixLength = minOf(n, 13)
    if (k > factorial[suffixLength]) {
        print("-1")
        return
    }

    val suffixStart = n - suffixLength + 1
    val available = MutableList(suffixLength) { suffixStart + it }
    val permutation = IntArray(suffixLength)
    var rank = k - 1

    for (i in 0 until suffixLength) {
        val remaining = suffixLength - i
        val blockSize = factorial[remaining - 1]
        val index = (rank / blockSize).toInt()
        rank %= blockSize
        permutation[i] = available.removeAt(index)
    }

    var answer = 0

    fun visitLucky(number: Long) {
        if (number > n) return

        if (number > 0) {
            val position = number.toInt()
            val value = if (position < suffixStart) {
                position
            } else {
                permutation[position - suffixStart]
            }

            if (isLucky(value)) answer++
        }

        visitLucky(number * 10 + 4)
        visitLucky(number * 10 + 7)
    }

    visitLucky(0)
    print(answer)
}

